  const [summary, setSummary] = useState(null);
  const [overallFee, setOverallFee] = useState(null);

  // Load overall structure for all visitors
  useEffect(() => {
    axios.get("http://localhost:5000/api/fees")
      .then(res => {
        if (res.data.success) setOverallFee(res.data.data);
      })
      .catch(() => toast.error("Failed to load overall fee structure"));
