    if (!admissionNo.trim()) return toast.error("Enter admission number");
    try {
      const res = await axios.get(`http://localhost:5000/api/fees/student/${admissionNo.trim()}`);
      if (res.data.success) {
        setSummary(res.data.data);
        toast.success("Student fee loaded");
      } else {
        setSummary(null);
        toast.error("No record found");
      }
    } catch {
      toast.error("Failed to fetch fee");
      setSummary(null);
    }
  };

  // Render categories
  const renderCategory = (category) => {
    const total = category.items.reduce((sum, i) => sum + (i.amount || 0), 0);
    return (
      <div key={category.title} className="fee-category">
        <h4>{category.title}</h4>
        <table className="fee-table">
          <thead>
            <tr>
              <th>Particulars</th>
              <th>Amount (₹)</th>
            </tr>
          </thead>
          <tbody>
            {category.items.map(it => (
              <tr key={it.key || it.title}>
                <td>{it.title}</td>
                <td>₹{it.amount}</td>
              </tr>
            ))}
            <tr>
              <td><b>Category Total</b></td>
              <td><b>₹{total}</b></td>
            </tr>
          </tbody>
        </table>
      </div>
    );
  };

  const renderFeeStructure = (fee) => {
    if (!fee) return null;
    const categories = fee.categories || [{ title: "Fees", items: Object.values(fee.items || {}) }];
    return (
      <div>
        {categories.map(cat => renderCategory(cat))}
        {fee.total !== undefined && <p><b>Total Fee: ₹{fee.total}</b></p>}
        {fee.paid !== undefined && <p>Paid: ₹{fee.paid} | Remaining: ₹{fee.remaining}</p>}
      </div>
    );
  };

  return (
    <div className="fee-page">
      <Toaster />
      <h2>💰 School Fee Structure</h2>

      {/* Always show overall */}
      {overallFee && (
        <div className="fee-card">
          <h3>Overall Fee Structure ({overallFee.academicYear})</h3>
          <div dangerouslySetInnerHTML={{ __html: overallFee.notes }} />
          {renderFeeStructure(overallFee)}
          <p>Enter your Admission No to see individual fees below.</p>
        </div>
      )}

      {/* Admission search */}
      <div className="search-box">
        <input
          type="text"
          placeholder="Admission No"
          value={admissionNo}
          onChange={e => setAdmissionNo(e.target.value)}
        />
        <button onClick={fetchFee}>Search</button>
      </div>

      {/* Student fee */}
      {summary && (
        <div className="fee-card">
          <h3>{summary.student.studentName}'s Fee</h3>
          {renderFeeStructure(summary.fee)}
        </div>
      )}
    </div>
  );
}






















































































